//! 📦️ Native body admissions retain actual backing before independently folding physical and allocation refusals.
use super::{NativeDecodeControl,OriginalReceivingPrimary};
use crate::{ValueError,ValueRefusalKind,RetirementDemand,RetainedWorkOutcome,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
impl NativeDecodeControl<'_>{
 /// 🧾️ Receives only an actual defining child outcome after its owner retained every effect; it grants no work or bytes.
 pub fn receive_retained_work(&mut self,grant:RetainedCloneGrant,turn:RetainedWorkOutcome)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{
  let progress=match &turn.result{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};let(step,mut primary)=match turn.result{Ok(step)=>(Some(step),None),Err(error)=>(None,Some(error))};if !progress.fits(grant)&&primary.is_none(){primary=Some(invalid("native defining receipt exceeds its actual physical grant").with_retained_progress(progress))}
  let before=self.owned_bytes;let mut allocation_refusal=None;match before.checked_add(progress.retained_capacity_bytes){Some(next)=>{self.owned_bytes=next;if progress.retained_capacity_bytes!=0{if let super::super::allocation::Binding::Forwarded(port)=&mut self.allocation{allocation_refusal=port(super::super::NativeDecodeAllocation{bytes:progress.retained_capacity_bytes,owned_bytes:before,next_owned_bytes:next,maximum_bytes:self.maximum_bytes}).err().map(|error|error.with_retained_progress(progress));}}if next>self.maximum_bytes&&allocation_refusal.is_none(){allocation_refusal=Some(ValueError::literal(ValueRefusalKind::OwnershipLimit,"native retained allocation exceeds its decoder ceiling").with_retained_progress(progress));}},None=>allocation_refusal=Some(ValueError::literal(ValueRefusalKind::OwnershipLimit,"native retained allocation extent overflow").with_retained_progress(progress))}
  let quote_refusal=self.construction.as_deref_mut().and_then(|recipient|recipient.accept(grant,progress).err()).map(|error|error.with_retained_progress(progress));let result=if primary.is_some()||quote_refusal.is_some()||allocation_refusal.is_some(){Err(OriginalReceivingPrimary{primary,quote_refusal,allocation_refusal,progress})}else{Ok(step.unwrap())};RetainedWorkOutcome{result,work:turn.work}
 }
 /// 🗂️ A typed destination keeps the real vector body before post-effect refusal; null keeps it empty.
 pub fn admit_vec<T>(&mut self,output:&mut Option<Vec<T>>,count:usize,grant:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{
  if output.is_some(){return RetainedWorkOutcome{result:Err(invalid("native vector admission requires an empty destination").into()),work:0}}let Some(bytes)=count.checked_mul(std::mem::size_of::<T>()).filter(|bytes|*bytes<=isize::MAX as usize)else{return RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"native vector size overflow").into()),work:0}};let demand=RetirementDemand{capacity_bytes:bytes,depth:1,..Default::default()};if !retained_clone_grant_admits(grant,demand){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}if self.owned_bytes.checked_add(bytes).is_none_or(|next|next>self.maximum_bytes){return RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"native vector exceeds decoder ceiling").into()),work:0}}if let Err(error)=self.checkpoint(){return RetainedWorkOutcome{result:Err(error.into()),work:0}}match self.prepare_work(1){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0},Err(e)=>return RetainedWorkOutcome{result:Err(e.into()),work:0}}let mut value=Vec::new();let result=match value.try_reserve_exact(count){Ok(())=>{let capacity=value.capacity().checked_mul(std::mem::size_of::<T>()).unwrap();*output=Some(value);Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,retained_capacity_bytes:capacity,..Default::default()}))},Err(_)=>Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"native vector backing allocation refused"))};self.commit_work(1).expect("one concrete native backing birth consumes only its held work");self.receive_retained_work(grant,RetainedWorkOutcome{result,work:1})
 }
 /// 🔤️ Actual UTF8 backing is allocated once and remains owned across every recipient refusal.
 pub fn admit_string(&mut self,output:&mut Option<String>,bytes:usize,grant:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{
  if output.is_some(){return RetainedWorkOutcome{result:Err(invalid("native text admission requires an empty destination").into()),work:0}}if bytes>isize::MAX as usize{return RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"native text size overflow").into()),work:0}}let demand=RetirementDemand{capacity_bytes:bytes,depth:1,..Default::default()};if !retained_clone_grant_admits(grant,demand){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}if self.owned_bytes.checked_add(bytes).is_none_or(|next|next>self.maximum_bytes){return RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"native text exceeds decoder ceiling").into()),work:0}}if let Err(error)=self.checkpoint(){return RetainedWorkOutcome{result:Err(error.into()),work:0}}match self.prepare_work(1){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0},Err(e)=>return RetainedWorkOutcome{result:Err(e.into()),work:0}}let mut value=String::new();let result=match value.try_reserve_exact(bytes){Ok(())=>{let capacity=value.capacity();*output=Some(value);Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,retained_capacity_bytes:capacity,..Default::default()}))},Err(_)=>Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"native text backing allocation refused"))};self.commit_work(1).expect("one concrete native backing birth consumes only its held work");self.receive_retained_work(grant,RetainedWorkOutcome{result,work:1})
 }
}
